function buildMermaid(text, kind){
  kind=kind||'flowchart';
  var lines=String(text||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;});
  var edges=[];
  lines.forEach(function(line){
    var m=line.match(/^([A-Za-z0-9_\u4e00-\u9fa5]+)\s*->+\s*([A-Za-z0-9_\u4e00-\u9fa5]+)\s*(?::|：)?\s*(.*)$/);
    if(m){ edges.push(m[1]+' -->'+(m[3]?('|'+m[3]+'|'):'')+' '+m[2]); }
    else { edges.push(line); }
  });
  var header = (kind==='sequence') ? 'sequenceDiagram' : 'flowchart TD';
  var body = edges.join('\n');
  return {code: header+'\n'+body, kind:kind, edgeCount:edges.length};
}
var EXPORTS={buildMermaid:buildMermaid};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MermaidForgePure = EXPORTS; }
